UPDATE iam_login_protection SET policy_digest=#{digest},
  blocked_until=GREATEST(blocked_until,clock_timestamp()+GREATEST(account_window_seconds,address_window_seconds,
    #{policy.accountWindowSeconds},#{policy.addressWindowSeconds})*interval '1 second'),
  account_attempts=#{policy.accountAttempts},account_window_seconds=#{policy.accountWindowSeconds},
  address_attempts=#{policy.addressAttempts},address_window_seconds=#{policy.addressWindowSeconds}
WHERE id=1 AND generation IS NOT NULL AND policy_digest=#{expected} AND policy_digest<>#{digest}
